function openSearch(){var e=document.getElementById("searchModal");if(e){e.classList.add("open");var a=document.getElementById("searchInput");a&&a.focus(),document.body.style.overflow="hidden"}}function closeSearch(){var e=document.getElementById("searchModal");e&&(e.classList.remove("open"),document.body.style.overflow="")}var _searchTimer=null;function handleSearch(e){if("Escape"!==e.key){var a=e.target.value.trim(),n=document.getElementById("searchResults");n&&(a.length<2?n.innerHTML="":(clearTimeout(_searchTimer),_searchTimer=setTimeout(function(){_doSearch(a,n)},300)))}else closeSearch()}function _doSearch(e,a){a.innerHTML='<div class="search-loading"><div class="spinner"></div><p>Поиск товаров...</p></div>',fetch("/catalog/search?q="+encodeURIComponent(e),{headers:{"X-Requested-With":"XMLHttpRequest"}}).then(function(e){return e.json()}).then(function(n){if(n.results&&n.results.length>0){var s=n.results.map(function(e){return'<a href="'+e.url+'" class="search-result-item"><img src="'+e.mainImage+'" alt="'+e.name+'" loading="lazy"><div class="search-result-info"><h4>'+e.name+'</h4><p class="search-result-brand">'+e.brand.name+'</p><p class="search-result-price">'+e.price+" BYN"+(e.oldPrice?'<span class="search-result-old-price">'+e.oldPrice+" BYN</span>":"")+"</p></div></a>"}).join("");a.innerHTML='<div class="search-results-list">'+s+'<a href="/catalog?q='+encodeURIComponent(e)+'" class="search-view-all">Посмотреть все результаты</a></div>'}else a.innerHTML='<div class="search-empty"><p>По запросу "'+e+'" ничего не найдено</p><a href="/catalog?q='+encodeURIComponent(e)+'" class="btn btn-primary">Посмотреть все товары</a></div>'}).catch(function(){a.innerHTML='<div class="search-error"><p>Ошибка при поиске. Попробуйте позже.</p></div>'})}document.addEventListener("DOMContentLoaded",function(){var e=document.getElementById("searchModal");e&&e.addEventListener("click",function(e){"searchModal"===e.target.id&&closeSearch()})});